import React, { useState, useEffect } from 'react';
import { FiMessageCircle, FiX, FiSend } from 'react-icons/fi';
import axios from 'axios';

const Chatbot = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [sessionId] = useState(`session-${Date.now()}`);
  const [loading, setLoading] = useState(false);

  const sendMessage = async (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    // Add user message
    setMessages(prev => [...prev, { sender: 'user', text: input }]);
    setInput('');
    setLoading(true);

    try {
      const response = await axios.post('http://localhost:5001/api/chatbot/chat', {
        message: input,
        sessionId,
        userId: localStorage.getItem('userId'),
      });

      setMessages(prev => [...prev, { sender: 'bot', text: response.data.botResponse }]);
    } catch (error) {
      setMessages(prev => [...prev, { sender: 'bot', text: 'Sorry, something went wrong. Please try again.' }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-50">
      {isOpen ? (
        <div className="bg-white rounded-2xl shadow-2xl w-96 h-[500px] flex flex-col border border-gray-200">
          <div className="bg-gradient-to-r from-black to-gray-800 text-white p-4 flex justify-between items-center rounded-t-2xl">
            <h3 className="font-semibold text-lg">AI Fashion Assistant</h3>
            <button onClick={() => setIsOpen(false)} className="hover:bg-blue-700 p-1 rounded">
              <FiX size={20} />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-gray-50">
            {messages.length === 0 && (
              <div className="bg-white p-4 rounded-lg shadow-sm">
                <p className="text-gray-700 text-sm">👋 Hi! I'm your AI fashion assistant. I can help you with:
                <br/>• Product recommendations
                <br/>• Size guidance
                <br/>• Order tracking
                <br/>• Return policy
                <br/><br/>How can I assist you today?</p>
              </div>
            )}
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`p-3 rounded-xl text-sm ${
                  msg.sender === 'user'
                    ? 'bg-black text-white ml-auto max-w-xs'
                    : 'bg-white text-gray-800 mr-auto max-w-xs shadow-sm border border-gray-100'
                }`}
              >
                {msg.text}
              </div>
            ))}
            {loading && <p className="text-gray-500 text-sm">Bot is typing...</p>}
          </div>

          <form onSubmit={sendMessage} className="border-t border-gray-200 p-4 flex gap-2 bg-white rounded-b-2xl">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Ask me anything..."
              className="flex-1 border border-gray-300 rounded-xl px-4 py-2.5 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent"
            />
            <button
              type="submit"
              disabled={loading}
              className="bg-black text-white px-4 py-2 rounded-xl hover:bg-gray-800 disabled:bg-gray-400 transition-colors"
            >
              <FiSend size={18} />
            </button>
          </form>
        </div>
      ) : (
        <button
          onClick={() => setIsOpen(true)}
          className="bg-black text-white p-4 rounded-full shadow-xl hover:bg-gray-800 transition-all hover:scale-110 group"
          title="Chat with AI Assistant"
        >
          <FiMessageCircle size={28} className="group-hover:animate-bounce" />
        </button>
      )}
    </div>
  );
};

export default Chatbot;
